INSERT INTO `model_metrics` (`id`, `model_version`, `evaluation_method`, `dataset_size`, `vocabulary_size`, `accuracy`, `precision_score`, `recall_score`, `f1_score`, `metrics_detail_json`, `trained_by`, `evaluated_at`) VALUES
(1, 'tfidf-logreg-nb-v1.180', 'Stratified 5-Fold Cross-Validation & 80/20 Hold-Out Split', 180, 2304, 0.9278, 0.9308, 0.9278, 0.9277, '{"status": "success", "model_version": "tfidf-logreg-nb-v1.180", "evaluation_method": "Stratified 5-Fold Cross-Validation & 80/20 Hold-Out Split", "dataset_size": 180, "class_distribution": {"positif": 60, "negatif": 60, "netral": 60}, "accuracy": 0.9278, "precision": 0.9308, "recall": 0.9278, "f1_score": 0.9277, "per_class": {"positif": {"precision": 0.9474, "recall": 0.9, "f1_score": 0.9231, "support": 60, "tp": 54, "fp": 3, "fn": 6}, "negatif": {"precision": 0.9643, "recall": 0.9, "f1_score": 0.931, "support": 60, "tp": 54, "fp": 2, "fn": 6}, "netral": {"precision": 0.8806, "recall": 0.9833, "f1_score": 0.9291, "support": 60, "tp": 59, "fp": 8, "fn": 1}}, "confusion_matrix": {"labels": ["positif", "negatif", "netral"], "matrix": [[54, 1, 5], [3, 54, 3], [0, 1, 59]]}, "holdout_80_20": {"accuracy": 0.9722, "precision_macro": 0.9744, "recall_macro": 0.9722, "f1_macro": 0.9722, "per_class": {"positif": {"precision": 1.0, "recall": 1.0, "f1_score": 1.0, "support": 12, "tp": 12, "fp": 0, "fn": 0}, "negatif": {"precision": 0.9231, "recall": 1.0, "f1_score": 0.96, "support": 12, "tp": 12, "fp": 1, "fn": 0}, "netral": {"precision": 1.0, "recall": 0.9167, "f1_score": 0.9565, "support": 12, "tp": 11, "fp": 0, "fn": 1}}, "confusion_matrix": {"labels": ["positif", "negatif", "netral"], "matrix": [[12, 0, 0], [0, 12, 0], [0, 1, 11]]}, "total_evaluated": 36, "correct_predictions": 35}, "evaluated_at": "2026-10-14 14:27:44", "Vocabulary_size": 2304, "trained_at": "2026-10-14 14:27:41"}', 1, '2026-10-14 14:27:44');
INSERT INTO `evaluations` (`id`, `evaluation_code`, `period_id`, `activity_id`, `faculty`, `study_program`, `is_anonymous`, `rating_materi`, `rating_pemateri`, `rating_panitia`, `rating_fasilitas`, `rating_konsumsi`, `rating_jadwal`, `rating_keseluruhan`, `comment_experience`, `comment_critique`, `is_dummy`, `submitted_at`) VALUES
(1, 'EV-2026-D001', 2, 3, 'Fakultas Ilmu Komputer', 'Teknik Informatika', 1, 5, 5, 5, 4, 4, 5, 5, 'Materinya sangat bermanfaat dan panitia sangat membantu.', 'Pertahankan keramahan panitia dan kualitas materi SIAKAD untuk tahun depan. [DATA DUMMY PENGUJIAN]', 1, '2026-09-07 11:45:00'),
(2, 'EV-2026-D002', 2, 4, 'Fakultas Teknik', 'Teknik Sipil', 1, 3, 3, 3, 2, 2, 1, 2, 'Jadwal kegiatan terlalu padat dan waktu istirahat kurang.', 'Mohon durasi istirahat sholat dan makan siang ditambah minimal menjadi 60 menit penuh. [DATA DUMMY PENGUJIAN]', 1, '2026-09-07 16:10:00'),
(3, 'EV-2026-D003', 2, 3, 'Fakultas Ekonomi dan Bisnis', 'Manajemen', 1, 4, 4, 4, 4, 4, 4, 4, 'Kegiatan PPKMB dilaksanakan selama tiga hari.', 'Buku panduan kegiatan sudah dibagikan melalui grup gugus masing-masing. [DATA DUMMY PENGUJIAN]', 1, '2026-09-07 12:15:00'),
(4, 'EV-2026-D004', 2, 3, 'Fakultas Ilmu Komputer', 'Sistem Informasi', 1, 5, 5, 5, 5, 4, 5, 5, 'Pemateri menyampaikan materi pengenalan akademik dengan sangat jelas, interaktif, dan tidak membosankan.', 'Simulasi pengisian KRS di layar besar sangat membantu mahasiswa baru. [DATA DUMMY PENGUJIAN]', 1, '2026-09-07 11:55:00'),
(5, 'EV-2026-D005', 2, 3, 'Fakultas Hukum', 'Ilmu Hukum', 1, 4, 4, 5, 2, 4, 4, 3, 'Suara mikrofon sering mati dan berdengung sehingga materi tidak terdengar dari barisan belakang.', 'Tolong tim perlengkapan mengecek sound system di bagian belakang auditorium sebelum sesi dimulai. [DATA DUMMY PENGUJIAN]', 1, '2026-09-07 12:05:00'),
(6, 'EV-2026-D006', 2, 4, 'Fakultas Ilmu Sosial dan Politik', 'Ilmu Komunikasi', 1, 5, 5, 5, 4, 4, 5, 5, 'Materi pencegahan kekerasan seksual di kampus disampaikan dengan sangat tegas, jelas, dan membuka wawasan.', 'Sangat mengapresiasi adanya kanal pelaporan Satgas PPKS yang disosialisasikan sejak hari pertama. [DATA DUMMY PENGUJIAN]', 1, '2026-09-07 16:00:00'),
(7, 'EV-2026-D007', 2, 4, 'Fakultas Teknik', 'Teknik Elektro', 1, 3, 3, 4, 2, 2, 2, 2, 'Ruangan aula sangat panas dan pengap pada siang hari karena AC di sayap kanan tidak berfungsi dengan baik.', 'Mohon perbaikan pendingin ruangan dan penambahan kipas blower di sisi kanan gedung. [DATA DUMMY PENGUJIAN]', 1, '2026-09-07 16:25:00'),
(8, 'EV-2026-D008', 2, 4, 'Fakultas Ekonomi dan Bisnis', 'Akuntansi', 1, 4, 4, 4, 4, 4, 4, 4, 'Sesi kedua diisi oleh pemateri dari Satgas PPKS dan berlangsung selama dua jam di auditorium.', 'Peserta duduk sesuai pembagian gugus masing-masing. [DATA DUMMY PENGUJIAN]', 1, '2026-09-07 16:30:00'),
(9, 'EV-2026-D009', 2, 5, 'Fakultas Ilmu Komputer', 'Teknik Informatika', 0, 5, 5, 5, 5, 5, 5, 5, 'Tur laboratorium komputer dan penjelasan kurikulum prodi sangat seru, kakak pendamping gugus juga ramah dan sabar.', 'Terima kasih kepada dosen wali dan kakak tingkat yang sudah menyambut kami dengan hangat. [DATA DUMMY PENGUJIAN]', 1, '2026-09-08 12:10:00'),
(10, 'EV-2026-D010', 2, 5, 'Fakultas Kedokteran dan Kesehatan', 'Kesehatan Masyarakat', 1, 2, 2, 3, 3, 2, 2, 2, 'Pembagian makan siang sangat terlambat dan sebagian nasi kotak sudah dingin ketika dibagikan ke gugus belakang.', 'Koordinasi divisi konsumsi harus diperbaiki agar distribusi makan siang tepat pukul 12.00. [DATA DUMMY PENGUJIAN]', 1, '2026-09-08 12:40:00'),
(11, 'EV-2026-D011', 2, 5, 'Fakultas Teknik', 'Teknik Industri', 1, 4, 4, 4, 4, 4, 4, 4, 'Sesi pengenalan jurusan dilaksanakan secara terpisah di ruang kelas gedung fakultas masing-masing.', 'Materi kurikulum dibagikan dalam format PDF melalui grup gugus. [DATA DUMMY PENGUJIAN]', 1, '2026-09-08 12:45:00'),
(12, 'EV-2026-D012', 2, 6, 'Fakultas Ilmu Sosial dan Politik', 'Administrasi Publik', 1, 5, 5, 5, 5, 4, 5, 5, 'Pembicara sesi mental health dan adaptasi kampus sangat keren, komunikatif, dan relevan bagi mahasiswa baru perantauan.', 'Semoga sesi konseling sebaya seperti ini diadakan rutin setiap semester. [DATA DUMMY PENGUJIAN]', 1, '2026-09-08 15:45:00'),
(13, 'EV-2026-D013', 2, 6, 'Fakultas Ekonomi dan Bisnis', 'Manajemen', 1, 2, 2, 3, 3, 3, 2, 2, 'Pemateri berbicara terlalu cepat dan sesi tanya jawab dipotong begitu saja karena waktu acara molor.', 'Manajemen waktu moderator perlu ditingkatkan agar mahasiswa tetap bisa bertanya. [DATA DUMMY PENGUJIAN]', 1, '2026-09-08 16:05:00'),
(14, 'EV-2026-D014', 2, 6, 'Fakultas Ilmu Komputer', 'Sains Data', 1, 5, 5, 4, 4, 5, 4, 5, 'Menu konsumsi hari kedua bervariasi, enak, dan higienis. Panitia konsumsi juga ramah mendata mahasiswa yang alergi.', 'Penyediaan air minum isi ulang di depan aula sangat bermanfaat untuk mengurangi sampah plastik. [DATA DUMMY PENGUJIAN]', 1, '2026-09-08 16:15:00'),
(15, 'EV-2026-D015', 2, 7, 'Fakultas Ilmu Komputer', 'Teknik Informatika', 1, 5, 5, 5, 4, 4, 5, 5, 'Expo UKM dan organisasi mahasiswa sangat meriah, tertib, dan memotivasi kami untuk aktif berorganisasi di kampus.', 'Penataan stand UKM di lapangan utama cukup rapi dan mudah dikunjungi per gugus. [DATA DUMMY PENGUJIAN]', 1, '2026-09-09 11:50:00'),
(16, 'EV-2026-D016', 2, 7, 'Fakultas Teknik', 'Teknik Mesin', 1, 3, 3, 2, 2, 2, 2, 2, 'Kurangnya ventilasi udara di tenda lapangan saat expo membuat suasana sangat panas dan antrean air minum habis.', 'Sebaiknya expo diadakan di hall indoor atau disediakan lebih banyak dispenser air minum di lapangan. [DATA DUMMY PENGUJIAN]', 1, '2026-09-09 12:15:00'),
(17, 'EV-2026-D017', 2, 7, 'Fakultas Hukum', 'Ilmu Hukum', 1, 4, 4, 4, 4, 4, 4, 4, 'Pada hari ketiga diadakan pengenalan unit kegiatan mahasiswa di lapangan utama mulai pukul 08.00 WIB.', 'Setiap gugus diberikan waktu keliling mengunjungi stand UKM secara bergiliran. [DATA DUMMY PENGUJIAN]', 1, '2026-09-09 12:25:00'),
(18, 'EV-2026-D018', 2, 8, 'Fakultas Ekonomi dan Bisnis', 'Akuntansi', 1, 5, 5, 5, 5, 5, 5, 5, 'Sangat puas dengan pelaksanaan PPKMB tahun ini, tidak ada perpeloncoan sama sekali, panitia humanis dan acara inagurasi sangat berkesan.', 'Terima kasih panitia PPKMB 2026 atas kerja keras dan pendampingan terbaiknya selama tiga hari! [DATA DUMMY PENGUJIAN]', 1, '2026-09-09 16:40:00'),
(19, 'EV-2026-D019', 2, 8, 'Fakultas Kedokteran dan Kesehatan', 'Pendidikan Dokter', 1, 3, 4, 2, 3, 3, 2, 2, 'Koordinasi antar panitia lapangan masih kurang kompak, informasi atribut dan penugasan sering berubah mendadak malam hari.', 'Mohon buku panduan penugasan dikunci sejak H-3 dan tidak diubah-ubah lagi pada tengah malam. [DATA DUMMY PENGUJIAN]', 1, '2026-09-09 16:50:00'),
(20, 'EV-2026-D020', 2, 8, 'Fakultas Ilmu Sosial dan Politik', 'Hubungan Internasional', 1, 5, 4, 5, 4, 4, 5, 5, 'Secara keseluruhan acara PPKMB sangat sukses, jadwal hari terakhir tepat waktu, dan tim medis sangat sigap membantu peserta.', 'Pertahankan konsep PPKMB edukatif dan ramah mahasiswa baru seperti tahun ini. [DATA DUMMY PENGUJIAN]', 1, '2026-09-09 17:00:00'),
(21, 'EV-2026-D021', 2, 8, 'Fakultas Ilmu Komputer', 'Sistem Informasi', 1, 5, 5, 4, 3, 3, 4, 5, 'Koneksi internet di gedung kegiatan mati total saat kami diminta mengisi presensi online dan toilet sempat kotor.', 'Mohon kapasitas bandwidth WiFi aula ditingkatkan saat seribu mahasiswa mengakses bersamaan. [DATA DUMMY PENGUJIAN]', 1, '2026-09-09 17:05:00'),
(22, 'EV-2025-D101', 1, 1, 'Fakultas Ilmu Komputer', 'Teknik Informatika', 1, 4, 4, 4, 3, 3, 3, 4, 'Materi pengenalan akademik cukup bermanfaat dan membantu mahasiswa memahami sistem SKS kampus.', 'Perlu peningkatan kualitas tata suara di auditorium. [DATA DUMMY PENGUJIAN]', 1, '2025-09-01 12:00:00'),
(23, 'EV-2025-D102', 1, 1, 'Fakultas Teknik', 'Teknik Sipil', 1, 3, 2, 2, 2, 2, 2, 2, 'Masih ada oknum panitia yang membentak-bentak saat baris-berbaris dan jadwal acara molor lebih dari satu jam.', 'Hentikan budaya bentak-bentak karena membuat suasana tegang dan tidak kondusif. [DATA DUMMY PENGUJIAN]', 1, '2025-09-01 15:30:00'),
(24, 'EV-2025-D103', 1, 1, 'Fakultas Ekonomi dan Bisnis', 'Manajemen', 1, 3, 3, 3, 2, 2, 2, 3, 'Ruangan sangat panas karena peserta terlalu padat dan pembagian konsumsi terlambat melewati jam makan siang.', 'Kapasitas gedung dan jadwal distribusi makan siang harus dievaluasi. [DATA DUMMY PENGUJIAN]', 1, '2025-09-01 16:00:00'),
(25, 'EV-2025-D104', 1, 2, 'Fakultas Hukum', 'Ilmu Hukum', 1, 4, 4, 4, 4, 3, 4, 4, 'Kegiatan hari kedua bertempat di gedung fakultas masing-masing mulai pukul 08.30 hingga 15.00 WIB.', 'Penyampaian materi dilakukan oleh dekanat dan ketua program studi. [DATA DUMMY PENGUJIAN]', 1, '2025-09-02 15:20:00'),
(26, 'EV-2025-D105', 1, 2, 'Fakultas Ilmu Sosial dan Politik', 'Ilmu Komunikasi', 1, 5, 5, 4, 4, 4, 4, 5, 'Dosen pemateri di fakultas sangat komunikatif, ramah, dan memberikan motivasi belajar yang bagus bagi mahasiswa baru.', 'Sesi diskusi dengan dosen wali sangat membantu. [DATA DUMMY PENGUJIAN]', 1, '2025-09-02 15:40:00'),
(27, 'EV-2025-D106', 1, 2, 'Fakultas Kedokteran dan Kesehatan', 'Kesehatan Masyarakat', 1, 2, 3, 2, 2, 2, 2, 2, 'Penjelasan teknis pengisian KRS sangat membingungkan, slide terlalu kecil tidak terbaca, dan waktu ishoma terlalu sempit.', 'Berikan panduan langkah demi langkah yang lebih jelas untuk mahasiswa baru. [DATA DUMMY PENGUJIAN]', 1, '2025-09-02 16:10:00');
INSERT INTO `sentiment_results` (`id`, `evaluation_id`, `sentiment_label`, `confidence_score`, `prob_positif`, `prob_negatif`, `prob_netral`, `analysis_status`, `is_ml`, `model_version`, `cleaned_text`, `rating_sentiment_discrepancy`, `analyzed_at`) VALUES
(1, 1, 'positif', 0.8855, 0.8855, 0.0662, 0.0484, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'materi sangat bermanfaat panitia sangat membantu pertahankan keramahan panitia kualitas materi siakad tahun depan _indikator_positif_ _indikator_positif_', 0, '2026-09-07 11:45:00'),
(2, 2, 'negatif', 0.8266, 0.0991, 0.8266, 0.0743, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'jadwal kegiatan terlalu padat waktu istirahat kurang_mohon kurang durasi istirahat sholat makan siang ditambah minimal menjadi menit penuh _indikator_negatif_ _indikator_negatif_', 0, '2026-09-07 16:10:00'),
(3, 3, 'netral', 0.9232, 0.0428, 0.0341, 0.9232, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'kegiatan ppkmb dilaksanakan selama tiga hari buku panduan kegiatan sudah dibagikan melalui grup gugus masing masing _indikator_netral_ _indikator_netral_', 0, '2026-09-07 12:15:00'),
(4, 4, 'positif', 0.8852, 0.8852, 0.0597, 0.0551, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'pemateri menyampaikan materi pengenalan akademik sangat jelas interaktif tidak_membosankan simulasi pengisian krs layar besar sangat membantu mahasiswa baru _indikator_positif_ _indikator_positif_', 0, '2026-09-07 11:55:00'),
(5, 5, 'negatif', 0.7233, 0.1374, 0.7233, 0.1393, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'suara mikrofon sering mati berdengung sehingga materi tidak_terdengar tidak barisan belakang tolong tim perlengkapan mengecek sound system bagian belakang auditorium sebelum sesi dimulai _indikator_negatif_ _indikator_negatif_', 0, '2026-09-07 12:05:00'),
(6, 6, 'positif', 0.7289, 0.7289, 0.1074, 0.1637, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'materi pencegahan kekerasan seksual kampus disampaikan sangat tegas jelas membuka wawasan sangat mengapresiasi adanya kanal pelaporan satgas ppks disosialisasikan sejak hari pertama _indikator_positif_', 0, '2026-09-07 16:00:00'),
(7, 7, 'negatif', 0.7923, 0.1121, 0.7923, 0.0956, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'ruangan aula sangat panas panas siang hari karena ac sayap kanan tidak_berfungsi tidak baik mohon perbaikan pendingin ruangan penambahan kipas blower sisi kanan gedung _indikator_negatif_ _indikator_negatif_', 0, '2026-09-07 16:25:00'),
(8, 8, 'netral', 0.8695, 0.0575, 0.0730, 0.8695, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'sesi kedua diisi pemateri satgas ppks berlangsung selama dua jam auditorium peserta duduk sesuai pembagian gugus masing masing _indikator_netral_ _indikator_netral_', 0, '2026-09-07 16:30:00'),
(9, 9, 'positif', 0.8109, 0.8109, 0.0870, 0.1021, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'tur laboratorium komputer penjelasan kurikulum prodi sangat seru kakak pendamping gugus juga ramah sabar terima kasih kepada dosen wali kakak tingkat sudah menyambut hangat _indikator_positif_ _indikator_positif_', 0, '2026-09-08 12:10:00'),
(10, 10, 'negatif', 0.5594, 0.2126, 0.5594, 0.2280, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'pembagian makan siang sangat terlambat sebagian nasi kotak sudah dingin ketika dibagikan gugus belakang koordinasi divisi konsumsi harus diperbaiki agar distribusi makan siang tepat pukul _indikator_negatif_', 0, '2026-09-08 12:40:00'),
(11, 11, 'netral', 0.8796, 0.0646, 0.0558, 0.8796, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'sesi pengenalan jurusan dilaksanakan secara terpisah ruang kelas gedung fakultas masing masing materi kurikulum dibagikan format pdf melalui grup gugus _indikator_netral_', 0, '2026-09-08 12:45:00'),
(12, 12, 'positif', 0.7834, 0.7834, 0.0823, 0.1344, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'pembicara sesi mental health adaptasi kampus sangat bagus komunikatif relevan bagi mahasiswa baru perantauan semoga sesi konseling sebaya seperti diadakan rutin setiap semester _indikator_positif_ _indikator_positif_', 0, '2026-09-08 15:45:00'),
(13, 13, 'negatif', 0.8133, 0.1159, 0.8133, 0.0708, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'pemateri berbicara terlalu cepat sesi tanya jawab dipotong begitu saja karena waktu acara terlambat manajemen waktu moderator perlu ditingkatkan agar mahasiswa tetap bisa berta _indikator_negatif_ _indikator_negatif_', 0, '2026-09-08 16:05:00'),
(14, 14, 'positif', 0.6824, 0.6824, 0.1483, 0.1693, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'menu konsumsi hari kedua bervariasi enak higienis panitia konsumsi juga ramah mendata mahasiswa alergi penyediaan air minum isi ulang depan aula sangat bermanfaat mengurangi sampah plastik _indikator_positif_ _indikator_positif_', 0, '2026-09-08 16:15:00'),
(15, 15, 'positif', 0.7365, 0.7365, 0.0907, 0.1728, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'expo ukm organisasi mahasiswa sangat meriah tertib memotivasi aktif berorganisasi kampus penataan stand ukm lapangan utama cukup rapi mudah dikunjungi per gugus _indikator_positif_ _indikator_positif_', 0, '2026-09-09 11:50:00'),
(16, 16, 'negatif', 0.7694, 0.1220, 0.7694, 0.1085, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'kurang ventilasi udara tenda lapangan saat expo membuat suasana sangat panas antrean air minum habis sebaik expo diadakan hall indoor disediakan lebih banyak dispenser air minum lapangan _indikator_negatif_ _indikator_negatif_', 0, '2026-09-09 12:15:00'),
(17, 17, 'netral', 0.8560, 0.0757, 0.0683, 0.8560, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'hari ketiga diadakan pengenalan unit kegiatan mahasiswa lapangan utama mulai pukul wib setiap gugus diberikan waktu keliling mengunjungi stand ukm secara bergiliran _indikator_netral_ _indikator_netral_', 0, '2026-09-09 12:25:00'),
(18, 18, 'positif', 0.8353, 0.8353, 0.0787, 0.0860, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'sangat puas pelaksanaan ppkmb tahun tidak_ada_perpeloncoan perpeloncoan sama sekali panitia humanis acara inagurasi sangat berkesan terima kasih panitia ppkmb atas kerja keras pendampingan terbaik selama tiga hari _indikator_positif_ _indikator_positif_', 0, '2026-09-09 16:40:00'),
(19, 19, 'negatif', 0.7896, 0.0859, 0.7896, 0.1244, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'koordinasi antar panitia lapangan masih kurang_kompak kurang informasi atribut penugasan sering berubah mendadak malam hari mohon buku panduan penugasan dikunci sejak tidak_diubah tidak ubah lagi tengah malam _indikator_negatif_ _indikator_negatif_', 0, '2026-09-09 16:50:00'),
(20, 20, 'positif', 0.8497, 0.8497, 0.0708, 0.0795, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'secara keseluruhan acara ppkmb sangat sukses jadwal hari terakhir tepat waktu tim medis sangat sigap membantu peserta pertahankan konsep ppkmb edukatif ramah mahasiswa baru seperti tahun _indikator_positif_ _indikator_positif_', 0, '2026-09-09 17:00:00'),
(21, 21, 'negatif', 0.7797, 0.1030, 0.7797, 0.1173, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'koneksi internet gedung kegiatan mati total saat diminta mengisi presensi online toilet sempat kotor mohon kapasitas bandwidth wifi aula ditingkatkan saat seribu mahasiswa mengakses bersamaan _indikator_negatif_ _indikator_negatif_', 1, '2026-09-09 17:05:00'),
(22, 22, 'positif', 0.7682, 0.7682, 0.1029, 0.1289, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'materi pengenalan akademik cukup bermanfaat membantu mahasiswa memahami sistem sks kampus perlu peningkatan kualitas tata suara auditorium _indikator_positif_ _indikator_positif_', 0, '2025-09-01 12:00:00'),
(23, 23, 'negatif', 0.8463, 0.0790, 0.8463, 0.0746, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'masih ada oknum panitia membentak membentak saat baris berbaris jadwal acara terlambat lebih satu jam hentikan budaya membentak membentak karena membuat suasana tegang tidak_kondusif tidak _indikator_negatif_ _indikator_negatif_', 0, '2025-09-01 15:30:00'),
(24, 24, 'negatif', 0.7780, 0.1171, 0.7780, 0.1049, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'ruangan sangat panas karena peserta terlalu padat pembagian konsumsi terlambat melewati jam makan siang kapasitas gedung jadwal distribusi makan siang harus dievaluasi _indikator_negatif_ _indikator_negatif_', 0, '2025-09-01 16:00:00'),
(25, 25, 'netral', 0.9222, 0.0388, 0.0390, 0.9222, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'kegiatan hari kedua bertempat gedung fakultas masing masing mulai pukul hingga wib penyampaian materi dilakukan dekanat ketua program studi _indikator_netral_ _indikator_netral_', 0, '2025-09-02 15:20:00'),
(26, 26, 'positif', 0.8624, 0.8624, 0.0568, 0.0808, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'dosen pemateri fakultas sangat komunikatif ramah memberikan motivasi belajar bagus bagi mahasiswa baru sesi diskusi dosen wali sangat membantu _indikator_positif_ _indikator_positif_', 0, '2025-09-02 15:40:00'),
(27, 27, 'negatif', 0.8205, 0.1158, 0.8205, 0.0637, 'analyzed', 1, 'tfidf-logreg-nb-v1.180', 'penjelasan teknis pengisian krs sangat membingungkan slide terlalu kecil tidak_terbaca tidak waktu ishoma terlalu sempit berikan panduan lang demi lang lebih jelas mahasiswa baru _indikator_negatif_ _indikator_negatif_', 0, '2025-09-02 16:10:00');
